//! 🧪️ Native map clone laws retain the original rows, cutoffs and physical denial axes.
use semio_framework_value_retained_map::{RetainedOrderedMap,RetainedOrderedMapCloneCursor,retained_clone::{RetainedClone,RetainedCloneCursor,RetainedCloneRef,RetainedCloneSource}};
use semio_framework_value_control_contract::*;
use semio_framework_value_retirement::{OriginalRetirementFailure,retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use semio_framework_value_clone_source_testing::FixtureSourceBirth;
use std::{marker::PhantomData,mem::size_of};
type Map=RetainedOrderedMap<u64,()>;
type Cursor=RetainedOrderedMapCloneCursor<u64,()>;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"native map demand {d:?}; cursor {}, retirement {}",size_of::<Cursor>(),size_of::<<Cursor as RetireOwned>::RetirementCursor>());RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut all=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes!=0{all.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})}if d.capacity_bytes!=0{all.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g})}if d.release_bytes!=0{all.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g})}if d.depth!=0{all.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g})}all}
fn paid<'a,'b,P>(bank:&mut EffectBank,authority:&mut OriginalEffectAuthority<P>,context:&mut P::Context<'a,'b>,g:RetainedCloneGrant,units:u64)->RetainedCloneStep where 'b:'a,P:OriginalEffectProducer<Output=RetainedCloneStep,Failure=OriginalRetirementFailure>{
 let(mut action,mut output)=(None,None);let mut heap=(0,0);let mut complete=false;
 for _ in 0..128{let((poll,actual),observed)=observe(||bank.run(g,units,|effect|{let before=effect.performed_boundary();let ready=authority.drive(context,effect,&mut action).unwrap();let work=effect.performed_since(before).unwrap();if ready{RetainedWorkPoll::Complete(RetainedWorkOutcome::<(),ValueError>{result:Ok(()),work})}else{RetainedWorkPoll::Pending{work}}}));heap.0+=observed.0;heap.1+=observed.1;if let Some(actual)=actual{assert_eq!(actual,heap.0)}if matches!(poll,RetainedWorkPoll::Pending{..}){continue}let progress=match action.as_ref().unwrap().recorded_reply().unwrap(){Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert!(progress.fits(g));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert_ne!(bank.take_admitted(),Some(false));bank.post(progress,g,heap);complete=true;break}
 assert!(complete,"native map action exceeded original bound");
 let g=grant(OriginalEffectAuthority::<P>::transfer_reply_demand().unwrap());let((poll,actual),heap)=observe(||bank.run(g,1,|effect|RetainedWorkPoll::Complete(authority.transfer_reply_into(context,&mut action,&mut output,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native transfer pending")};assert_eq!(actual,None);assert_ne!(bank.take_admitted(),Some(false));bank.post(turn.result.unwrap().unwrap(),g,heap);
 let answer=*output.as_ref().unwrap().as_ref().unwrap();let d=RetirementDemand{copy_bytes:size_of::<Option<Result<RetainedCloneStep,OriginalRetirementFailure>>>(),depth:1,..Default::default()};let g=grant(d);let((poll,actual),heap)=observe(||bank.run(g,1,|effect|{assert!(effect.performed(1).unwrap());drop(output.take());RetainedWorkPoll::Complete(RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}),work:1})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native reply retirement pending")};assert_eq!(actual,None);assert_ne!(bank.take_admitted(),Some(false));bank.post(turn.result.unwrap(),g,heap);answer
}
struct CloneDriver;
struct CloneContext<'a,'b>{cursor:&'a mut Cursor,input:RetainedCloneRef<'b,Map>,source:OriginalSourceTurnIdentity}
impl OriginalEffectProducer for CloneDriver{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=CloneContext<'a,'b>where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.source)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.cursor.advance_into(c.input,7,64,effect,reply)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.cursor.recover_advance_into(c.input,7,64,effect,reply)}
}
struct TakeDriver{reply:Option<Result<RetainedCloneStep,ValueError>>}
impl OriginalEffectProducer for TakeDriver{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut Cursor,&'a mut Option<Map>,OriginalSourceTurnIdentity)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.2)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{let done=c.0.take(c.1,effect,OriginalEffectReply::borrow(&mut self.reply)?)?;drop(done);semio_framework_value_retained_map::retained_clone::forward_original_value_reply(&mut self.reply,reply)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{if self.reply.is_none(){let done=c.0.recover_take(c.1,effect,OriginalEffectReply::borrow(&mut self.reply)?)?;drop(done)}semio_framework_value_retained_map::retained_clone::forward_original_value_reply(&mut self.reply,reply)}
}
struct RetireDriver<T:RetireOwned>(PhantomData<T>);
impl<T:RetireOwned> OriginalEffectProducer for RetireDriver<T>{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=(&'a mut ControlledRetirement<T>,OriginalSourceTurnIdentity)where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.1)}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.0.step_into(7,effect,reply)}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>where 'b:'a{c.0.recover_step_into(7,effect,reply)}
}
fn retire<T:RetireOwned>(value:T,bank:&mut EffectBank){let mut owner=ControlledRetirement::retain(value);let mut authority=OriginalEffectAuthority::new(RetireDriver::<T>(PhantomData));for _ in 0..10000{if owner.terminal_is_empty(){break}let g=grant(owner.next_demand(7).unwrap());let work=owner.next_computational_work(7).unwrap();let source=bank.source_witness().identity();paid(bank,&mut authority,&mut(&mut owner,source),g,work);}assert!(owner.terminal_is_empty());assert!(authority.into_producer().is_ok());}
#[test]
fn native_map_clone_preserves_all_original_rows_cancellation_denials_and_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("native.json")).unwrap();assert_eq!(Cursor::birth_prefix_actions(),Some(law["birthPrefixActions"].as_u64().unwrap()as usize));assert_eq!(<(u64,()) as RetainedClone>::NATIVE_CURSOR_SEED.unwrap().part_count(),law["innerTupleSeedParts"].as_u64().unwrap()as usize);
 for count in law["entryCounts"].as_array().unwrap(){let count=count.as_u64().unwrap();for stop in std::iter::once(None).chain(law["interruptAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()))){let bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let input=(0..count).map(|key|(key,())).collect::<Map>();let mut fixture=RetainedCloneSource::from_owner_in(input,bank);fixture.with_bank(|input,bank|{
  let mut cursor=Map::retained_clone_cursor();let mut authority=OriginalEffectAuthority::new(CloneDriver);let mut completed=false;
  for turn in 0..law["maximumTurns"].as_u64().unwrap(){if stop.is_some_and(|cut|turn>=cut){break}let demand=cursor.advance_demands(input,7,64).unwrap();let units=cursor.advance_work_demand(input,7,64).unwrap();let g=grant(demand);for denied in denied(g,demand){let source=bank.source_witness().identity();let before=*bank.wallet().original_work();let step=paid(bank,&mut authority,&mut CloneContext{cursor:&mut cursor,input,source},denied,units);assert_eq!(step.progress(),Default::default());assert_eq!(*bank.wallet().original_work(),before-2);assert_eq!(cursor.advance_demands(input,7,64).unwrap(),demand)}let source=bank.source_witness().identity();let step=paid(bank,&mut authority,&mut CloneContext{cursor:&mut cursor,input,source},g,units);if matches!(step,RetainedCloneStep::Complete(_)){completed=true;break}}
  if stop.is_none(){assert!(completed);assert!(cursor.output_ready());let mut output=None;let mut take=OriginalEffectAuthority::new(TakeDriver{reply:None});let g=grant(cursor.take_demand().unwrap());let work=cursor.take_work_demand().unwrap();let source=bank.source_witness().identity();paid(bank,&mut take,&mut(&mut cursor,&mut output,source),g,work);let output=output.take().expect("native cloned map");assert_eq!(output.iter().map(|(key,())|*key).collect::<Vec<_>>(),(0..count).collect::<Vec<_>>());assert_eq!(serde_json::to_value(&output).unwrap(),serde_json::to_value((0..count).map(|key|(key,())).collect::<std::collections::BTreeMap<_,_>>()).unwrap());assert!(take.into_producer().is_ok());retire(output,bank);}assert_eq!(input.get().iter().map(|(key,())|*key).collect::<Vec<_>>(),(0..count).collect::<Vec<_>>());assert!(authority.into_producer().is_ok());retire(cursor,bank);
 }).unwrap();for _ in 0..law["maximumTurns"].as_u64().unwrap(){if fixture.terminal_is_empty(){break}fixture.close_once().unwrap();}assert!(fixture.terminal_is_empty());}}
}
